package com.greenlink.controller; import com.greenlink.dto.PlantView;import com.greenlink.security.AppUserPrincipal;import com.greenlink.service.PlantService;import java.util.List;import org.bson.types.ObjectId;import org.springframework.http.ResponseEntity;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/plants") public class PlantController {private final PlantService s;public PlantController(PlantService s){this.s=s;} @GetMapping public List<PlantView> all(@RequestParam(required=false) String search){return s.all(search);} @GetMapping("/{id}") public PlantView one(@PathVariable String id){return s.one(new ObjectId(id));} @PostMapping(consumes="multipart/form-data") public ResponseEntity<PlantView> create(@AuthenticationPrincipal AppUserPrincipal p,@RequestParam String name,@RequestParam(required=false,defaultValue="") String scientificName,@RequestParam(required=false,defaultValue="") String description,@RequestParam(required=false,defaultValue="") String careInstructions,@RequestPart(value="image",required=false) MultipartFile image){return ResponseEntity.status(201).body(s.create(new ObjectId(p.getId()),name,scientificName,description,careInstructions,image));} @PutMapping(value="/{id}",consumes="multipart/form-data") public PlantView update(@AuthenticationPrincipal AppUserPrincipal p,@PathVariable String id,@RequestParam(required=false) String name,@RequestParam(required=false) String scientificName,@RequestParam(required=false) String description,@RequestParam(required=false) String careInstructions,@RequestPart(value="image",required=false) MultipartFile image){return s.update(new ObjectId(p.getId()),new ObjectId(id),name,scientificName,description,careInstructions,image);} @DeleteMapping("/{id}") public MapResponse delete(@AuthenticationPrincipal AppUserPrincipal p,@PathVariable String id){s.delete(new ObjectId(p.getId()),new ObjectId(id));return new MapResponse("Plant deleted successfully");} public record MapResponse(String message){} }
